function minThreshold(nums, k) {
  const sorted = [...new Set(nums)].sort((a, b) => a - b);
  const size = sorted.length;
  const tree = new Array(size + 1).fill(0);
  // How many distinct values are <= limit: the rank of the largest such value.
  function rankAtMost(limit) {
    let left = 0;
    let right = size;
    while (left < right) {
      const middle = (left + right) >> 1;
      if (sorted[middle] <= limit) {
        left = middle + 1;
      } else {
        right = middle;
      }
    }
    return left;
  }
  function add(rank) {
    for (let i = rank; i <= size; i += i & -i) {
      tree[i]++;
    }
  }
  function prefix(rank) {
    let total = 0;
    for (let i = rank; i > 0; i -= i & -i) {
      total += tree[i];
    }
    return total;
  }
  const ranks = nums.map(value => rankAtMost(value));
  function countPairs(threshold) {
    tree.fill(0);
    let pairs = 0;
    for (let j = 0; j < nums.length; j++) {
      const top = rankAtMost(nums[j] + threshold);
      pairs += prefix(top) - prefix(ranks[j]);
      add(ranks[j]);
    }
    return pairs;
  }
  let low = 1;
  let high = sorted[size - 1] - sorted[0];
  if (high < 1 || countPairs(high) < k) {
    return -1;
  }
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (countPairs(mid) >= k) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low;
}

