function minThreshold(nums, k) {
  // List the gap of every inversion pair; the k-th smallest gap is the least threshold that admits k pairs.
  const gaps = [];
  for (let i = 0; i < nums.length; i++)
    for (let j = i + 1; j < nums.length; j++)
      if (nums[i] > nums[j]) gaps.push(nums[i] - nums[j]);
  if (gaps.length < k) return -1;
  gaps.sort((a, b) => a - b);
  return gaps[k - 1];
}

