function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  if (size === 'large') {
    const top = pick([5, 1000, 1000000000]);
    const nums = Array.from({ length: 2000 }, () => 1 + Math.floor(rand() * top));
    // Sometimes descending, so nearly every pair is an inversion.
    if (rand() < 0.3) nums.sort((a, b) => b - a);
    return [nums, 1 + Math.floor(rand() * 1000000)];
  }
  const n = 1 + Math.floor(rand() * 10);
  const top = pick([2, 3, 10, 100, 1000000000]);
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  let inversions = 0;
  for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) if (nums[i] > nums[j]) inversions++;
  // Usually k is reachable; sometimes it is one more than the inversions, which makes the answer -1.
  return [nums, rand() < 0.15 ? inversions + 1 : 1 + Math.floor(rand() * Math.max(1, inversions))];
}
